"""Public Instagram acquisition hub, regenerated with the existing Site build."""
import html,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def esc(t):return html.escape(str(t),quote=True)
def hub():
    q=json.loads((ROOT/'content/instagram-queue.json').read_text())
    body='''<section class="zi-ig-intro"><div class="wrap"><span class="zi-kicker">BIENVENUE DEPUIS INSTAGRAM</span><h1>Du journal<br>à votre chantier.</h1><p>Comprendre les matériaux. Découvrir notre activité. Préparer votre demande.</p><div class="zi-ig-links"><a href="/actualites/?utm_source=instagram&amp;utm_medium=organic_social&amp;utm_campaign=bio_journal"><span>01 / LE JOURNAL</span><strong>Lire & comprendre ↗</strong><small>Actualités et décryptages sourcés</small></a><a href="/#catalogue"><span>02 / VOS MATÉRIAUX</span><strong>Découvrir les gammes ↗</strong><small>Matériaux de construction</small></a><a href="#demande"><span>03 / VOTRE CHANTIER</span><strong>Préparer une demande ↓</strong><small>Fourniture et livraison selon faisabilité</small></a></div></div></section><section class="section"><div class="wrap"><div class="zi-kicker">LE TERRAIN, EN IMAGES</div><h2>Une lecture utile. Des photos réelles.</h2><p class="intro">Guides pratiques et vues de notre activité. Ces photographies ne constituent pas une disponibilité de stock en temps réel.</p><div class="zi-ig-grid">'''
    for p in q['posts']:
        body+='<details class="zi-ig-post"><summary><img src="'+esc(p['images'][0])+'" alt="'+esc(p['title'])+' — première diapositive" width="1080" height="1350" loading="lazy"><span>'+esc(p['series'])+'</span><strong>'+esc(p['title'])+'</strong><small>Ouvrir le carrousel · 4 vues →</small></summary><div class="zi-ig-slides">'+''.join('<a href="'+esc(src)+'" target="_blank" rel="noopener"><img src="'+esc(src)+'" alt="'+esc(s['title']+' '+s['body'])+'" width="1080" height="1350" loading="lazy"></a>' for src,s in zip(p['images'],p['slides']))+'</div><p class="zi-ig-caption">'+esc(p['caption'])+'</p></details>'
    body+='<p><a class="zi-ig-service-link" href="/actualites/arrivage-fer-beton-fardeaux-barres-12m/">Lire le reportage fer à béton →</a><a class="zi-ig-service-link" href="/actualites/panneaux-muraux-stock-et-pose-en-images/">Lire le reportage panneaux muraux →</a></p>'
    body+='''</div></div></section><section class="section zi-ig-demand" id="demande"><div class="wrap"><span class="zi-kicker">BANANA MATÉRIAUX</span><h2>Parlons de votre chantier.</h2><p>Quatre informations pour préparer votre demande. Vous choisissez ensuite de l’envoyer sur WhatsApp.</p><form id="ig-request"><div class="fields"><div class="field"><label for="ig-material">Matériau / référence</label><input id="ig-material" required maxlength="150" placeholder="Ex. fer à béton T10"></div><div class="field"><label for="ig-quantity">Quantité et unité</label><input id="ig-quantity" required maxlength="80" placeholder="Ex. 2 tonnes"></div><div class="field"><label for="ig-place">Ville / lieu du chantier</label><input id="ig-place" required maxlength="150" placeholder="Ex. Bouskoura"></div><div class="field"><label for="ig-date">Échéance souhaitée</label><input id="ig-date" required maxlength="80" placeholder="Ex. semaine prochaine"></div></div><p class="hint">Ces informations restent dans votre navigateur jusqu’à votre envoi sur WhatsApp. Aucun envoi automatique.</p><button class="btn" type="submit">Préparer mon message WhatsApp ↗</button></form><a href="/#transport" class="zi-ig-service-link">Découvrir l’organisation des livraisons →</a><a href="/#references" class="zi-ig-service-link">Voir nos références →</a></div></section>'''
    return body
